#!/usr/bin/env python3
"""Probe zcode app-server wire protocol: spawn, send candidate messages, print replies."""
import subprocess, threading, sys, time, json, os

PROC = ["osascript", "-e", "do shell script \"true\""]  # placeholder replaced below
ZCODE = os.path.expanduser("~/.local/bin/zcode")

def reader(pipe, tag):
    try:
        for line in iter(pipe.readline, b""):
            print(f"[{tag}] {line.decode(errors='replace').rstrip()[:300]}", flush=True)
    except Exception:
        pass

def probe(msgs, wait=4):
    p = subprocess.Popen([ZCODE, "app-server"], stdin=subprocess.PIPE,
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    for tag, pipe in (("out", p.stdout), ("err", p.stderr)):
        threading.Thread(target=reader, args=(pipe, tag), daemon=True).start()
    time.sleep(2)
    for m in msgs:
        data = m if isinstance(m, bytes) else (json.dumps(m) if not isinstance(m, str) else m)
        if isinstance(data, str):
            data = data.encode()
        print(f">>> {data[:160]}", flush=True)
        try:
            p.stdin.write(data + b"\n")
            p.stdin.flush()
        except Exception as e:
            print("stdin closed:", e); break
        time.sleep(wait)
    p.terminate()
    time.sleep(1)

candidates = [
    "",
    '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}',
    '{"type":"initialize"}',
    '{"op":"initialize"}',
]
probe(candidates)

