#!/usr/bin/env python3
"""zcode-ask: 让外部 agent（如 codex CLI）委派任务给 ZCode 的桥接命令。
用法: zcode-ask [工作目录] "任务描述"
原理: 驱动 `zcode app-server`（ZCode Protocol v1），完整复刻桌面端的会话引导：
  注册账号 provider（updateAccountConfig）→ 应答运行时偏好 → 创建会话 →
  回应认证头索要（requestProviderRuntimeHeaders，注入 API Key）→ 发送任务 → 轮询取回答。
凭据: ~/.zcode/v2/apikey.txt（编码计划 API Key，0600）。
"""
import subprocess, threading, json, time, os, sys, re

ZCODE = os.path.expanduser("~/.local/bin/zcode")
W = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 and os.path.isdir(sys.argv[1]) else os.getcwd()
PROMPT = sys.argv[2] if len(sys.argv) > 2 else (sys.argv[1] if len(sys.argv) > 1 else "你好")
PROVIDER = "account:bigmodel-start-plan"
MODEL_ID = "GLM-5.3-Flash"
MODEL = {"providerId": PROVIDER, "modelId": MODEL_ID, "options": {"reasoningLevel": "max"}}
BASED_ON = "zcode-builtin:30:5e721907cbd9c09784934b30d0b12858f626638e83a67ac61787d1de65d16eaf"
KEY_FILE = os.path.expanduser("~/.zcode/v2/apikey.txt")
API_KEY = open(KEY_FILE).read().strip() if os.path.isfile(KEY_FILE) else None
TIMEOUT = int(os.environ.get("ZCODE_ASK_TIMEOUT", "240"))

p = subprocess.Popen([ZCODE, "app-server"], stdin=subprocess.PIPE,
                     stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
raw = []
sess_id = [None]
turn_done = [False]
texts = []

AUTH_HEADERS = {}
if API_KEY:
    [REDACTED:SECRET_ASSIGNMENT] = {"Authorization": "Bearer " + API_KEY,
                    "x-api-key": API_KEY,
                    "X-Bigmodel-Authorization": "Bearer " + API_KEY,
                    "x-coding-plan-api-key": API_KEY}

def reply(jid, result):
    p.stdin.write((json.dumps({"id": jid, "result": result}) + "\n").encode())
    p.stdin.flush()

def handle(j):
    m = j.get("method", "")
    if m == "session/requestRuntimePreferences":
        if not sess_id[0]:
            sess_id[0] = j["params"]["sessionId"]
        reply(j["id"], {"nativeSearchEnhancementsEnabled": False, "memoryEnabled": False,
                        "askUserQuestionAutoResolutionEnabled": True,
                        "modelContextBudgetStrategy": "preflight-v1"})
    elif m == "interaction/requestProviderRuntimeHeaders":
        if AUTH_HEADERS:
            reply(j["id"], {"headersApplied": True, "headers": AUTH_HEADERS})
        else:
            reply(j["id"], {"headersApplied": False,
                            "errorMessage": "bridge: no apikey.txt"})
    elif m == "interaction/requestOfficialMcpAuthHeaders":
        reply(j["id"], {"headersApplied": False})
    elif m == "interaction/requestPermission":
        reply(j["id"], {"decision": "allow"})
    elif m == "session/event":
        s = json.dumps(j.get("params", {}), ensure_ascii=False)
        for t in re.findall(r'"text":"((?:[^"\\]|\\.)*)"', s):
            if t: texts.append(t)
        if re.search(r'"(status|phase|kind)"\s*:\s*"(complete|finished|idle|ended|done|turn-complete)"', s):
            turn_done[0] = True
        if "turn-failed" in s or '"failed"' in s:
            turn_done[0] = True

def rd():
    for line in iter(p.stdout.readline, b""):
        try:
            handle(json.loads(line.decode(errors="replace")))
        except Exception:
            pass
        try:
            with lock:
                raw.append(raw and None or None)
        except Exception:
            pass

lock = threading.Lock()
def rd_fixed():
    for line in iter(p.stdout.readline, b""):
        try:
            j = json.loads(line.decode(errors="replace"))
        except Exception:
            continue
        with lock:
            raw.append(j)
        try:
            handle(j)
        except Exception:
            pass

threading.Thread(target=rd_fixed, daemon=True).start()
time.sleep(3)

def send(obj, wait=4):
    p.stdin.write((json.dumps(obj) + "\n").encode()); p.stdin.flush()
    time.sleep(wait)

def wait_reply(rid, timeout=45):
    end = time.time() + timeout
    while time.time() < end:
        with lock:
            for j in raw:
                if j.get("id") == rid and ("result" in j or "error" in j):
                    return j
        time.sleep(0.5)
    return None

def die(msg):
    print("ERROR %s" % msg, file=sys.stderr)
    p.terminate(); sys.exit(1)

# 1) 注册账号 provider（复刻桌面端的注册表快照）
send({"id": 1, "method": "provider/updateAccountConfig", "params": {
    "revision": "bridge-%d" % int(time.time()), "basedOnZCodeBuiltinRevision": BASED_ON,
    "providers": {PROVIDER: {"builtinModelIds": ["GLM-5.3", "GLM-5.3-Flash"],
                             "access": {"type": "zhipu-account", "entitled": True}}},
    "states": {PROVIDER: {"availability": "available", "entitled": True, "current": True}}}})
r = wait_reply(1, 20)
if not r or "error" in r:
    die("provider register: %s" % json.dumps(r, ensure_ascii=False)[:200] if r else "timeout")

# 2) 创建会话（实体化 + MCP 启动）
send({"id": 2, "method": "session/create",
      "params": {"workspace": {"workspacePath": W, "workspaceKey": W}}})
