#!/usr/bin/env python3
"""zcode-relay: 常驻中继，让沙箱内的 zcode-ask 能用 ZCode。
监听 ~/.zcode/bridge.sock；每个连入的客户端对应一个新的 `zcode app-server`
子进程（stdio 双向转发）。由 LaunchAgent 常驻，沙箱外的它负责所有文件写入。
"""
import os, socket, subprocess, threading

ZCODE = os.path.expanduser("~/.local/bin/zcode")
SOCK = os.path.expanduser("~/.zcode/bridge.sock")

def pipe(a_r, a_w, b_r, b_w):
    try:
        while True:
            data = a_r.recv(65536)
            if not data:
                break
            b_w.write(data)
            b_w.flush()
    except Exception:
        pass
    finally:
        try: b_w.close()
        except Exception: pass

def handle(conn):
    proc = subprocess.Popen([ZCODE, "app-server"], stdin=subprocess.PIPE,
                            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    t1 = threading.Thread(target=pipe, args=(conn, None, proc.stdout, proc.stdin), daemon=True)
    def back():
        try:
            while True:
                data = proc.stdout.readline()
                if not data:
                    break
                conn.sendall(data)
        except Exception:
            pass
        finally:
            try: conn.close()
            except Exception: pass
    t2 = threading.Thread(target=back, daemon=True)
    t1.start(); t2.start()
    proc.wait()
    try: conn.close()
    except Exception: pass

def main():
    try: os.unlink(SOCK)
    except FileNotFoundError:
        pass
    srv = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    srv.bind(SOCK)
    os.chmod(SOCK, 0o666)
    srv.listen(4)
    print("zcode-relay listening on", SOCK, flush=True)
    while True:
        conn, _ = srv.accept()
        threading.Thread(target=handle, args=(conn,), daemon=True).start()

if __name__ == "__main__":
    main()

