原理: 驱动 `zcode app-server`（ZCode Protocol v1），完整复刻桌面端的会话引导：
  注册账号 provider（updateAccountConfig）→ 应答运行时偏好 → 创建会话 →
  回应认证头索要（requestProviderRuntimeHeaders，注入 API Key）→ 发送任务 → 轮询取回答。
凭据: ~/.zcode/v2/apikey.txt（编码计划 API Key，0600）。
"""
import subprocess, threading, json, time, os, sys, re

ZCODE = os.path.expanduser("~/.local/bin/zcode")
W = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 and os.path.isdir(sys.argv[1]) else os.getcwd()
PROMPT = sys.argv[2] if len(sys.argv) > 2 else (sys.argv[1] if len(sys.argv) > 1 else "你好")
PROVIDER = "account:bigmodel-start-plan"
MODEL_ID = "GLM-5.3-Flash"
MODEL = {"providerId": PROVIDER, "modelId": MODEL_ID, "options": {"reasoningLevel": "max"}}
import glob
def _ready_log():
    logs = sorted(glob.glob(os.path.expanduser("~/.zcode/cli/log/zcode-*.jsonl")))
    return logs[-1] if logs else None

def _read_ready_events():
    log = _ready_log()
    if not log: return []
    try:
        with open(log, errors="replace") as f:
            f.seek(0, 2); size = f.tell(); f.seek(max(0, size - 400000))
            tail = f.read()
    except Exception:
        return []
    return re.findall(r'account:\["(zcode-builtin:[0-9a-f:]+)"', tail)

def wait_fresh_based_on(baseline_count, timeout=25):
    """等中继子进程自己的 registry ready 事件出现（出现即注册表就绪）"""
    end = time.time() + timeout
    while time.time() < end:
        evs = _read_ready_events()
        if len(evs) > baseline_count and evs:
            return evs[-1]
        time.sleep(1)
    evs = _read_ready_events()
    return evs[-1] if evs else None

BASELINE = len(_read_ready_events())
KEY_FILE = os.path.expanduser("~/.zcode/v2/apikey.txt")
JWT_FILE = os.path.expanduser("~/.zcode/v2/jwt.txt")

def fresh_jwt():
    """从桌面端凭据文件现场解密 OAuth JWT（桌面端续期后这里自动跟上）"""
    script = '''
const crypto=require("node:crypto"),os=require("node:os"),fs=require("node:fs");
const creds=JSON.parse(fs.readFileSync(os.homedir()+"/.zcode/v2/credentials.json","utf8"));
const enc=creds["zcodejwttoken"];
if(!enc||!enc.startsWith("enc:v1:"))process.exit(1);
const secret=process.env.ZCODE_CREDENTIAL_SECRET?.trim()||`zcode-credential-fallback:${process.platform}:${os.homedir()}:${os.userInfo().username}`;
const k=crypto.createHash("sha256").update(secret).digest();
const [i,t,c]=enc.slice(7).split(".");
const d=crypto.createDecipheriv("aes-256-gcm",k,Buffer.from(i,"base64url"));
d.setAuthTag(Buffer.from(t,"base64url"));
process.stdout.write(Buffer.concat([d.update(Buffer.from(c,"base64url")),d.final()]).toString("utf8"));'''
    electron = "/Applications/ZCode.app/Contents/MacOS/ZCode"
    zcjs = "/Applications/ZCode.app/Contents/Resources/glm/zcode.cjs"
    try:
        r = subprocess.run(["/usr/bin/env", "ELECTRON_RUN_AS_NODE=1", electron, "-e", script],
                           capture_output=True, text=True, timeout=30,
                           env=dict(os.environ, ELECTRON_RUN_AS_NODE="1"))
        tok = r.stdout.strip()
        return tok if tok.startswith("eyJ") else None
    except Exception:
        return None

API_KEY = None
JWT = fresh_jwt()
if not JWT and os.path.isfile(JWT_FILE):
    JWT = open(JWT_FILE).read().strip() or None
if not JWT and os.path.isfile(KEY_FILE):
    API_KEY = open(KEY_FILE).read().strip() or None
TIMEOUT = int(os.environ.get("ZCODE_ASK_TIMEOUT", "240"))

import socket as _socket
BRIDGE_SOCK = os.path.expanduser("~/.zcode/bridge.sock")

class ProcLike:
    """中继连接适配成 Popen 一样的 stdin/stdout 接口"""
    def __init__(self, sock):
        self.sock = sock
        self._r = sock.makefile("rb")
        self._w = sock.makefile("wb")
    def write(self, data):
        return self._w.write(data)
    def flush(self):
        return self._w.flush()
    def readline(self):
        return self._r.readline()
    def terminate(self):
        try: self.sock.close()
        except Exception: pass
    def kill(self):
        self.terminate()

def open_channel():
    """优先连接常驻中继（TCP，沙箱内可行；unix 备用），失败则直启 app-server"""
    if os.environ.get("ZCODE_ASK_DIRECT") != "1":
        for mk in (("AF_INET", ("127.0.0.1", 47612)), ("AF_UNIX", BRIDGE_SOCK)):
            try:
                s = _socket.socket(getattr(_socket, mk[0]), _socket.SOCK_STREAM)
                s.settimeout(5)
                s.connect(mk[1])
                s.settimeout(None)
                return ProcLike(s), True
            except Exception:
                try: s.close()
                except Exception: pass
    if os.environ.get("ZCODE_ASK_NO_FILE_FALLBACK") != "1" and "--internal-run" not in sys.argv:
        return None, "file"  # 沙箱环境：走文件接力
    proc = subprocess.Popen([ZCODE, "app-server"], stdin=subprocess.PIPE,
                            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    class _P:
        def __init__(self, p): self._p = p
        def write(self, d): return self._p.stdin.write(d)
        def flush(self): return self._p.stdin.flush()
        def readline(self): return self._p.stdout.readline()
        def terminate(self): self._p.terminate()
        def kill(self): self._p.kill()
    return _P(proc), False

TASK_DIR = os.path.join(os.environ.get("TMPDIR") or "/tmp", "zcode-bridge")

def run_file_drop(w, prompt, timeout):
    """沙箱内模式：把任务写进共享临时目录，等中继（沙箱外）写回结果"""
    os.makedirs(TASK_DIR, exist_ok=True)
    tid = os.urandom(8).hex()
    fin = os.path.join(TASK_DIR, tid + ".in")
    fout = os.path.join(TASK_DIR, tid + ".out")
    with open(fin, "w") as f:
        json.dump({"cwd": w, "prompt": prompt, "timeout": timeout}, f, ensure_ascii=False)
    end = time.time() + timeout + 90
    while time.time() < end:
        time.sleep(2)
        if os.path.exists(fout):
            try:
                with open(fout) as f:
                    r = json.load(f)
            finally:
                try: os.remove(fout)
                except Exception: pass
                try: os.remove(fin)
                except Exception: pass
            print(r.get("response") or r.get("error") or "(空结果)")
            return
    print("(接力超时：任务文件 %s 已保留，中继可能未运行)" % tid)

def internal_run(inpath, outpath):
    """中继侧调用：读取任务文件，直接执行完整会话，写回结果"""
    with open(inpath) as f:
        task = json.load(f)
    resp = {"response": None, "error": None}
    try:
        W2 = task["cwd"]; PROMPT2 = task["prompt"]; TIMEOUT2 = task.get("timeout", 240)
        _sess = _run_session(W2, PROMPT2, TIMEOUT2)
        resp["response"] = _sess
    except SystemExit:
        raise
    except Exception as e:
        resp["error"] = "%s: %s" % (type(e).__name__, e)
    with open(outpath, "w") as f:
        json.dump(resp, f, ensure_ascii=False)
    try: os.remove(inpath)
    except Exception: pass

def _run_session(w, prompt, timeout):
    """原来的主流程（直启 app-server 完整跑一轮），返回最终文本"""
    raise RuntimeError("placeholder-replaced-below")

chan, via_relay = open_channel()
p = chan
if chan is None:
    run_file_drop(W, PROMPT, TIMEOUT)  # 不再返回
    sys.exit(0)
raw = []
sess_id = [None]
turn_done = [False]
texts = []

AUTH_HEADERS = {}
if API_KEY:
    [REDACTED:SECRET_ASSIGNMENT] = {"Authorization": "Bearer " + API_KEY,
                    "x-api-key": API_KEY,
                    "X-Bigmodel-Authorization": "Bearer " + API_KEY,
