#!/usr/bin/env python3
"""zcode-ask: 让外部 agent（如 codex CLI）委派任务给 ZCode 的桥接命令。
用法: zcode-ask [工作目录] "任务描述"
通道（自动选择）:
  1. 常驻中继 ~/.zcode/bridge.sock（unix）
  2. 常驻中继 tcp://127.0.0.1:47612
  3. 文件接力 $TMPDIR/zcode-bridge/（Codex 沙箱内唯一可行：只靠文件读写，
     由沙箱外的 zcode-relay 守护进程认领执行）
  4. 直启 app-server（ZCODE_ASK_DIRECT=1 或以上全失败且不在沙箱限制下）
协议: ZCode Protocol v1（zcode app-server），复刻桌面端引导：
  注册账号 provider → 应答运行时偏好 → 创建会话 → 回应认证头索要（注入
  现场解密的 OAuth JWT）→ 发送任务 → 轮询取回答。
"""
import subprocess, threading, json, time, os, sys, re, glob, socket as _socket

ZCODE = os.path.expanduser("~/.local/bin/zcode")
PROVIDER = "account:bigmodel-start-plan"
MODEL = {"providerId": PROVIDER, "modelId": "GLM-5.3-Flash",
         "options": {"reasoningLevel": "max"}}
BRIDGE_SOCK = os.path.expanduser("~/.zcode/bridge.sock")
TCP_ADDR = ("127.0.0.1", 47612)
TASK_DIR = os.path.join(os.environ.get("TMPDIR") or "/tmp", "zcode-bridge")
TIMEOUT = int(os.environ.get("ZCODE_ASK_TIMEOUT", "240"))

# ---------- 凭据：现场解密桌面端 OAuth JWT（桌面端续期后自动跟上） ----------
def fresh_jwt():
    script = '''
const crypto=require("node:crypto"),os=require("node:os"),fs=require("node:fs");
const creds=JSON.parse(fs.readFileSync(os.homedir()+"/.zcode/v2/credentials.json","utf8"));
const enc=creds["zcodejwttoken"];
if(!enc||!enc.startsWith("enc:v1:"))process.exit(1);
const secret=process.env.ZCODE_CREDENTIAL_SECRET?.trim()||`zcode-credential-fallback:${process.platform}:${os.homedir()}:${os.userInfo().username}`;
const k=crypto.createHash("sha256").update(secret).digest();
const [i,t,c]=enc.slice(7).split(".");
const d=crypto.createDecipheriv("aes-256-gcm",k,Buffer.from(i,"base64url"));
d.setAuthTag(Buffer.from(t,"base64url"));
process.stdout.write(Buffer.concat([d.update(Buffer.from(c,"base64url")),d.final()]).toString("utf8"));'''
    try:
        r = subprocess.run(
            ["/Applications/ZCode.app/Contents/MacOS/ZCode", "-e", script],
            capture_output=True, text=True, timeout=30,
            env=dict(os.environ, ELECTRON_RUN_AS_NODE="1"))
        tok = r.stdout.strip()
        return tok if tok.startswith("eyJ") else None
    except Exception:
        return None

JWT = fresh_jwt()
KEY_FILE = os.path.expanduser("~/.zcode/v2/apikey.txt")
API_KEY = (open(KEY_FILE).read().strip() if os.path.isfile(KEY_FILE) else None) if not JWT else None

# ---------- 注册表 basedOn：从共享日志读当前进程自己的快照（每次启动都变） ----------
def _read_ready_events():
    logs = sorted(glob.glob(os.path.expanduser("~/.zcode/cli/log/zcode-*.jsonl")))
    if not logs: return []
    try:
        with open(logs[-1], errors="replace") as f:
            f.seek(0, 2); size = f.tell(); f.seek(max(0, size - 400000))
            tail = f.read()
    except Exception:
        return []
    return re.findall(r'account:\["(zcode-builtin:[0-9a-f:]+)"', tail)

def wait_fresh_based_on(baseline_count, timeout=25):
    end = time.time() + timeout
    while time.time() < end:
        evs = _read_ready_events()
        if len(evs) > baseline_count and evs:
            return evs[-1]
        time.sleep(1)
    evs = _read_ready_events()
    return evs[-1] if evs else None

# ---------- 通道 ----------
class ProcLike:
    def __init__(self, sock):
        self.sock = sock
        self._r = sock.makefile("rb")
        self._w = sock.makefile("wb")
    def write(self, d): return self._w.write(d)
    def flush(self): return self._w.flush()
    def readline(self): return self._r.readline()
    def terminate(self):
        try: self.sock.close()
        except Exception: pass
    def kill(self): self.terminate()

def open_channel():
    """依次尝试：TCP 中继 → unix 中继 → 文件接力(None) → 直启"""
    for mk, addr in (("AF_INET", TCP_ADDR), ("AF_UNIX", BRIDGE_SOCK)):
        try:
            s = _socket.socket(getattr(_socket, mk), _socket.SOCK_STREAM)
            s.settimeout(4)
            s.connect(addr)
            s.settimeout(None)
            return ProcLike(s)
        except Exception:
            try: s.close()
            except Exception: pass
    if "--internal-run" in sys.argv or os.environ.get("ZCODE_ASK_DIRECT") == "1":
        proc = subprocess.Popen([ZCODE, "app-server"], stdin=subprocess.PIPE,
                                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        class _P:
            def __init__(self, p): self._p = p
            def write(self, d): return self._p.stdin.write(d)
            def flush(self): return self._p.stdin.flush()
            def readline(self): return self._p.stdout.readline()
            def terminate(self): self._p.terminate()
            def kill(self): self._p.kill()
        return _P(proc)
    return None  # 文件接力

# ---------- 会话主流程 ----------
def run_session(w, prompt, timeout=TIMEOUT, chan=None):
    own = chan is None
