            raise RuntimeError("no channel available")
    p = chan
    raw, sess_id, turn_done, texts = [], [None], [False], []
    baseline = len(_read_ready_events())
    lock = threading.Lock()

    def reply(jid, result):
        p.write((json.dumps({"id": jid, "result": result}) + "\n").encode()); p.flush()

    def handle(j):
        m = j.get("method", "")
        if m == "session/requestRuntimePreferences":
            if not sess_id[0]:
                sess_id[0] = j["params"]["sessionId"]
            reply(j["id"], {"nativeSearchEnhancementsEnabled": False, "memoryEnabled": False,
                            "askUserQuestionAutoResolutionEnabled": True,
                            "modelContextBudgetStrategy": "preflight-v1"})
        elif m == "interaction/requestProviderRuntimeHeaders":
            tok = JWT or API_KEY
            if tok:
                reply(j["id"], {"headersApplied": True, "requestAuth": {"apiKey": tok}})
            else:
                reply(j["id"], {"headersApplied": False, "errorMessage": "bridge: no credentials"})
        elif m == "interaction/requestOfficialMcpAuthHeaders":
            reply(j["id"], {"headersApplied": False})
        elif m == "interaction/requestPermission":
            reply(j["id"], {"decision": "allow"})
        elif m == "session/event":
            s = json.dumps(j.get("params", {}), ensure_ascii=False)
            for t in re.findall(r'"text":"((?:[^"\\]|\\.)*)"', s):
                if t: texts.append(t)
            if re.search(r'"(status|phase|kind)"\s*:\s*"(complete|finished|idle|ended|done|turn-complete)"', s):
                turn_done[0] = True
            if "turn-failed" in s or '"failed"' in s:
                turn_done[0] = True

    def rd():
        for line in iter(p.readline, b""):
            try: j = json.loads(line.decode(errors="replace"))
            except Exception: continue
            with lock: raw.append(j)
            try: handle(j)
            except Exception: pass

    threading.Thread(target=rd, daemon=True).start()
    time.sleep(3)
    based_on = wait_fresh_based_on(baseline) or _read_ready_events()[-1]

    def send(obj, wait=3):
        p.write((json.dumps(obj) + "\n").encode()); p.flush(); time.sleep(wait)

    def wait_reply(rid, tout=45):
        end = time.time() + tout
        while time.time() < end:
            with lock:
                for j in raw:
                    if j.get("id") == rid and ("result" in j or "error" in j):
                        return j
            time.sleep(0.5)
        return None

    def die(msg):
        err = Exception("bridge: " + msg)
        try: p.terminate()
        except Exception: pass
        raise err

    # 1) 注册账号 provider
    send({"id": 1, "method": "provider/updateAccountConfig", "params": {
        "revision": "bridge-%d" % int(time.time()), "basedOnZCodeBuiltinRevision": based_on,
        "providers": {PROVIDER: {"builtinModelIds": ["GLM-5.3", "GLM-5.3-Flash"],
                                 "access": {"type": "zhipu-account", "entitled": True}}},
        "states": {PROVIDER: {"availability": "available", "entitled": True, "current": True}}}})
    r = wait_reply(1, 20)
    if not r or "error" in r:
        die("provider register: %s" % (json.dumps(r, ensure_ascii=False)[:160] if r else "timeout"))
    # 2) 创建会话
    send({"id": 2, "method": "session/create",
          "params": {"workspace": {"workspacePath": w, "workspaceKey": w}}}, 6)
    r = wait_reply(2, 60)
    if not r or "error" in r:
        die("create: %s" % (json.dumps(r.get("error", {}), ensure_ascii=False)[:160] if r else "timeout"))
    # 3) 发送任务（模型选择 + 认证注入）
    params = {"sessionId": sess_id[0], "content": prompt, "modelSelection": MODEL}
    tok = JWT or API_KEY
    if tok:
        params["modelExecution"] = {"selectionScope": "execution", "requestAuth": {"apiKey": tok}}
    send({"id": 4, "method": "session/send", "params": params}, 4)
    r = wait_reply(4, 30)
    if not r or "error" in r:
        die("send: %s" % (json.dumps(r.get("error", {}), ensure_ascii=False)[:160] if r else "timeout"))
    # 4) 等轮次结束，拉取消息
    end = time.time() + timeout
    while time.time() < end and not turn_done[0]:
        time.sleep(4)
    if not turn_done[0]:
        time.sleep(8)
    send({"id": 9, "method": "session/messages", "params": {"sessionId": sess_id[0]}}, 2)
    wait_reply(9, 15)
    try: p.terminate()
    except Exception: pass
    parts = []
    def walk(o):
        if isinstance(o, dict):
            if o.get("type") == "text" and isinstance(o.get("text"), str):
                parts.append(o["text"])
            for v in o.values(): walk(v)
        elif isinstance(o, list):
            for v in o: walk(v)
