        for j in raw:
            if j.get("id") == 9 and "result" in j:
                walk(j["result"])
    out = [t for t in parts if t != prompt]
    text = re.sub(r"\n{3,}", "\n\n", "\n".join(out[-3:])).strip()
    return text or "(无文本；会话 %s 保留)" % sess_id[0]

# ---------- 文件接力（沙箱客户端 ⇆ 沙箱外中继） ----------
def run_file_drop(w, prompt, timeout):
    os.makedirs(TASK_DIR, exist_ok=True)
    tid = os.urandom(8).hex()
    fin, fout = os.path.join(TASK_DIR, tid + ".in"), os.path.join(TASK_DIR, tid + ".out")
    with open(fin, "w") as f:
        json.dump({"cwd": w, "prompt": prompt, "timeout": timeout}, f, ensure_ascii=False)
    end = time.time() + timeout + 120
    while time.time() < end:
        time.sleep(2)
        if os.path.exists(fout):
            try:
                with open(fout) as f: r = json.load(f)
            finally:
                try: os.remove(fout)
                except Exception: pass
            print(r.get("response") or r.get("error") or "(空结果)")
            return
    print("(接力超时：任务 %s 未被中继认领——检查 LaunchAgent com.local.zcode-bridge)" % tid)

def internal_run(inpath, outpath):
    with open(inpath) as f:
        task = json.load(f)
    resp = {}
    try:
        resp["response"] = run_session(task["cwd"], task["prompt"], task.get("timeout", 240))
    except SystemExit:
        raise
    except Exception as e:
        resp["error"] = "%s: %s" % (type(e).__name__, e)
    with open(outpath, "w") as f:
        json.dump(resp, f, ensure_ascii=False)
    try: os.remove(inpath)
    except Exception: pass

# ---------- 入口 ----------
if __name__ == "__main__":
    if "--internal-run" in sys.argv:
        i = sys.argv.index("--internal-run")
        internal_run(sys.argv[i + 1], sys.argv[i + 2])
        sys.exit(0)
    w = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 and os.path.isdir(sys.argv[1]) else os.getcwd()
    prompt = sys.argv[2] if len(sys.argv) > 2 else (sys.argv[1] if len(sys.argv) > 1 else "你好")
